  let pairs=[['leftHand','leftGrip.mainGrab'],['rightHand','rightGrip.mainGrab'],['leftFoot','leftPeg.riderSupport'],['rightFoot','rightPeg.riderSupport'],['pelvis','seat.topSupport'],['chest','tank.chestBrace']];
  for(let [e,n] of pairs){let vi=DATA.effectors[e],k=vi*3,p=[a.runtime.pos[k],a.runtime.pos[k+1],a.runtime.pos[k+2]],q=affordancePoint(co[n]);if(q)overlayPush(lp,lc,p,q,colLink)}
